import{_ as t}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as a,o as i,c as o,al as d}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"Guided Course Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_modes_fw/guided_course.md","filePath":"ko/flight_modes_fw/guided_course.md"}'),r={name:"ko/flight_modes_fw/guided_course.md"};function n(s,e,l,c,m,h){return i(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="guided-course-mode-fixed-wing" tabindex="-1">Guided Course Mode (Fixed-Wing) <a class="header-anchor" href="#guided-course-mode-fixed-wing" aria-label="Permalink to &quot;Guided Course Mode (Fixed-Wing)&quot;">​</a></h1><img src="'+t+'" title="Position required (e.g. GPS)" width="30px"><p><em>Guided Course mode</em> maintains a constant ground track (course), altitude, and airspeed without any manual stick input. The operator controls the vehicle entirely using <a href="#supported-commands">GCS commands</a>, making it the guided equivalent of <a href="./../flight_modes_fw/cruise">Cruise mode</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This mode is suited to situations where an operator wants to guide a fixed-wing vehicle from a GCS without manual control.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Requires a horizontal velocity estimate (e.g. GPS/dead-reckoning). Course commands will be rejected if the velocity estimate is unavailable.</li><li>Manual control input is ignored.</li></ul></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>On activation, the vehicle captures its current velocity over ground vector as the initial course bearing and holds altitude and airspeed from the moment of activation. The vehicle then flies that course indefinitely until the operator issues a new command.</p><p>There is no waypoint sequencing or autonomous path planning: the GCS guides the vehicle in real time by sending individual commands.</p><h2 id="supported-commands" tabindex="-1">Supported Commands <a class="header-anchor" href="#supported-commands" aria-label="Permalink to &quot;Supported Commands&quot;">​</a></h2><p>The following commands are accepted while in Guided Course mode:</p><table tabindex="0"><thead><tr><th>통신</th><th>Effect</th></tr></thead><tbody><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_GUIDED_CHANGE_HEADING" target="_blank" rel="noreferrer">MAV_CMD_GUIDED_CHANGE_HEADING</a></td><td>Set a new course bearing (degrees, 0 = north) with <code>HEADING_TYPE = 0</code>. Rejected if horizontal velocity estimate is unavailable.</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_ALTITUDE" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_ALTITUDE</a></td><td>Set a new target altitude (AMSL, metres).</td></tr><tr><td><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a></td><td>Set a new equivalent airspeed via param2 (m/s). If param2 ≤ 0, the default cruise speed is restored.</td></tr></tbody></table><h2 id="technical-description" tabindex="-1">Technical Description <a class="header-anchor" href="#technical-description" aria-label="Permalink to &quot;Technical Description&quot;">​</a></h2><p>The navigator mode (<code>course.cpp</code>) sets a position setpoint with <code>course</code> (ground track bearing) and <code>alt</code> fields populated, and <code>yaw = NAN</code>.</p><p>The fixed-wing mode manager (<code>FixedWingModeManager</code>) detects the finite <code>course</code> field and bypasses normal waypoint sequencing, calling <code>navigateBearing()</code> from the directional guidance library to compute lateral acceleration and course setpoints. Longitudinal control targets the altitude and airspeed from the setpoint.</p><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position_relaxed"><code>mode_req_local_position_relaxed</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_wind_and_flight_time_compliance"><code>mode_req_wind_and_flight_time_compliance</code></a> — Safety compliance limits on wind and flight time.</li></ul><h3 id="failsafe-behaviour" tabindex="-1">Failsafe Behaviour <a class="header-anchor" href="#failsafe-behaviour" aria-label="Permalink to &quot;Failsafe Behaviour&quot;">​</a></h3><p>Guided Course is classified as an <code>AUTO</code> mode for failsafe purposes. The following failsafe exception parameters apply:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Bit</th><th>Effect when set</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a></td><td>1 (Auto modes)</td><td>RC loss does not trigger a failsafe in this mode.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#COM_DLL_EXCEPT">COM_DLL_EXCEPT</a></td><td>1 (Auto modes)</td><td>GCS connection loss does not trigger a failsafe.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Since Guided Course is driven entirely by GCS commands, operators should carefully consider the datalink loss failsafe setting (<code>COM_DLL_EXCEPT</code> bit 1). If the GCS link drops, the vehicle will continue on its last commanded course indefinitely. It is strongly recommended to either leave the datalink failsafe active or ensure a secondary safety mechanism (e.g. geofence, battery failsafe) is in place.</p></div><h2 id="매개변수" tabindex="-1">매개변수 <a class="header-anchor" href="#매개변수" aria-label="Permalink to &quot;매개변수&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>설명</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a></td><td>Default cruise airspeed used on activation and when <code>MAV_CMD_DO_CHANGE_SPEED</code> is sent with value ≤ 0.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a></td><td>Minimum airspeed. Commanded airspeed is clamped to this value.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a></td><td>Maximum airspeed. Commanded airspeed is clamped to this value.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#COM_RCL_EXCEPT">COM_RCL_EXCEPT</a></td><td>RC loss failsafe exceptions bitmask. Bit 1 covers all auto modes including Guided Course.</td></tr><tr><td><a href="./../advanced_config/parameter_reference#COM_DLL_EXCEPT">COM_DLL_EXCEPT</a></td><td>Datalink loss failsafe exceptions bitmask. Bit 1 covers all auto modes including Guided Course.</td></tr></tbody></table>',23)])])}const p=a(r,[["render",n]]);export{f as __pageData,p as default};
